\set ON_ERROR_STOP on
BEGIN;
SET LOCAL standard_conforming_strings = on;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE SCHEMA IF NOT EXISTS portfolio;
CREATE TABLE IF NOT EXISTS portfolio.assets(id TEXT PRIMARY KEY, properties JSONB NOT NULL, geom geometry(Point,4326) NOT NULL);
DELETE FROM portfolio.assets;
CREATE INDEX IF NOT EXISTS assets_geom_idx ON portfolio.assets USING gist(geom);
CREATE TABLE IF NOT EXISTS portfolio.centers(id TEXT PRIMARY KEY, properties JSONB NOT NULL, geom geometry(Point,4326) NOT NULL);
DELETE FROM portfolio.centers;
CREATE INDEX IF NOT EXISTS centers_geom_idx ON portfolio.centers USING gist(geom);
CREATE TABLE IF NOT EXISTS portfolio.zones(id TEXT PRIMARY KEY, properties JSONB NOT NULL, geom geometry(Polygon,4326) NOT NULL);
DELETE FROM portfolio.zones;
CREATE INDEX IF NOT EXISTS zones_geom_idx ON portfolio.zones USING gist(geom);
CREATE TABLE IF NOT EXISTS portfolio.hazards(id TEXT PRIMARY KEY, properties JSONB NOT NULL, geom geometry(Polygon,4326) NOT NULL);
DELETE FROM portfolio.hazards;
CREATE INDEX IF NOT EXISTS hazards_geom_idx ON portfolio.hazards USING gist(geom);
CREATE OR REPLACE VIEW portfolio.analysis AS
WITH measured AS (
 SELECT a.id,a.properties->>'name' AS name,a.properties->>'condition' AS condition,
 c.id AS nearest_center,ST_Distance(a.geom::geography,c.geom::geography) AS distance_m,
 ST_DWithin(a.geom::geography,c.geom::geography,750) AS covered,
 EXISTS(SELECT 1 FROM portfolio.hazards h WHERE ST_Covers(h.geom,a.geom)) AS hazard,
 ('2026-10-25'::date-(a.properties->>'last_inspected')::date)>180 AS overdue
 FROM portfolio.assets a CROSS JOIN LATERAL (
 SELECT * FROM portfolio.centers c ORDER BY ST_Distance(a.geom::geography,c.geom::geography),c.id LIMIT 1) c
), scored AS (SELECT *,CASE WHEN condition='REPAIR' THEN 35 ELSE 0 END+CASE WHEN overdue THEN 25 ELSE 0 END+CASE WHEN hazard THEN 25 ELSE 0 END+CASE WHEN NOT covered THEN 15 ELSE 0 END AS score FROM measured)
SELECT *,CASE WHEN score>=60 THEN 'P1' WHEN score>=30 THEN 'P2' ELSE 'P3' END AS priority FROM scored;
COMMIT;
SELECT priority,count(*) FROM portfolio.analysis GROUP BY priority ORDER BY priority;
